import XCTest
@testable import Tomi

/// The texts come from one catalog for the phones and the Mac: a text that names the device has its two wordings
/// (device variations generated by tools/strings-from-android.py), plurals included. Whatever the language of the
/// run: every language names the Mac "Mac".
final class TextsTests: XCTestCase {
    func testAPluralNamesTheDeviceItRunsOn() {
        let several = L10n.plural("pair_history_body", 3)
        let one = L10n.plural("pair_history_body", 1)
        XCTAssertTrue(several.contains("3"), several)
        XCTAssertTrue(one.contains("1"), one)
        XCTAssertNotEqual(several.replacingOccurrences(of: "3", with: "1"), one, "the language's own singular")
        #if os(macOS)
        XCTAssertTrue(several.contains("Mac"), several)
        XCTAssertTrue(one.contains("Mac"), one)
        #else
        XCTAssertFalse(several.contains("Mac"), several)
        #endif
    }

    func testATextNamesTheDeviceItRunsOn() {
        #if os(macOS)
        XCTAssertTrue(L10n.text("erase_confirm").contains("Mac"))
        #else
        XCTAssertFalse(L10n.text("erase_confirm").contains("Mac"))
        #endif
    }
}
